package com.cryptoloan.notification.adapters.out.persistence;import com.cryptoloan.notification.domain.model.Notification.Status;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="notifications")class NotificationJpaEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=254)String recipient;@Column(nullable=false,length=60)String type;@Column(nullable=false,length=180)String subject;@Column(nullable=false,length=2000)String message;@Column(name="loan_id")Long loanId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)Status status;@Column(length=300)String error;@Column(name="created_at",nullable=false)Instant createdAt;}

